export XZ_WS_URL='wss://api.tenclass.net/xiaozhi/v1/' XZ_BARGE_ANY=0
# 小智本地唤醒脚本：公共会话锁、独立 processed PCM 订阅、定向事件。
# 官方“小爱同学”由固件接管：先收净本会话，再交给官方。
# 所有本地词命中后都先结束当前会话，再重连对应路径，包括同名词。
# WEBD-UNINSTALL-TIMEOUT: 30
XZ_CLIENT_SHA256='cb0b047018e5d4b4dbc1d9c100e1e7e8b6113a2808bb30e6728965780790a129'
BASE=/data/lx06/xiaozhi
SETTINGS=/usr/lib/lx06/script-settings
